	name = "Español",
	listed = false,
	translators = { "fmartingr" },
	plural = function(n)
		if n == 1 then
			return "one"
		end
		if n ~= 0 and n == math.floor(n) and n % 1000000 == 0 then
			return "many"
		end
		return "other"
	end,
	decimal = ",",
	thousands = ".",
})
